def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "transfer_ice_into_pitcher": And([
            Not(self.container_stable),
            self.humans_present,
            self.floor_surface_smooth,
            Not(self.large_container_on_counter)
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
